// The Error Trigger sends two different shapes:
//   node failure    -> { execution: { id, url, error, lastNodeExecuted, mode }, workflow: {...} }
//   trigger failure -> { trigger:   { error, mode },                            workflow: {...} }
// Read whichever one arrived.
const j = $input.first().json;
const e = j.execution || j.trigger || {};
const err = e.error || {};

const workflowName = (j.workflow || {}).name || 'Unknown workflow';
const workflowId   = (j.workflow || {}).id   || '';
const nodeName     = e.lastNodeExecuted || '(trigger / startup)';
const message      = err.message || 'No error message was provided.';
const stack        = (err.stack || '').split('\n').slice(0, 6).join('\n').trim();

const subject = `n8n workflow failed: ${workflowName}`;

const body = [
  `Workflow : ${workflowName}`,
  `Node     : ${nodeName}`,
  `Error    : ${message}`,
  '',
  `Time     : ${new Date().toISOString()}`,
  e.mode ? `Mode     : ${e.mode}` : null,
  e.id   ? `Execution: ${e.id}`   : null,
  workflowId ? `Workflow ID: ${workflowId}` : null,
  e.url  ? `\nOpen the run: ${e.url}` : null,
  stack  ? `\n--- Stack (first 6 lines) ---\n${stack}` : null,
].filter(Boolean).join('\n');

return [{ json: { subject, body, workflowName, nodeName, message } }];
